\newcommand{\lsmooth}[1]{\left(L_0+L_1\|\nabla f(x_{#1})\|\right)}


\newcommand{\Gconstant}{8\overline{\Delta}_1+8+32\log^2\frac{T}{\delta}+8\frac{\sqrt{2C}}{\sqrt{L_0T}}\log\frac{T}{\delta}+\frac{303L_0}{224L_1^2}}


\newcommand{\functiongapboundconstant}{\overline{\Delta}_c}


We consider the stochastic optimization problem that 
\begin{align}
  \label{problem}
  \min\limits_{x\in\mathbb{R}^d} f(x)=\mathbb{E}_{z \sim \mathcal{D}}[f_z(x;z)],
\end{align}

where the objective function $f(x)$ is possibly non-convex and $\mathcal{D}$ is a probability distribution from which the random vector $z$ is drawn.


\begin{definition}[$\left(L_0,L_1\right)$-smoothness]
  \label{definition 1}
  Let $f(x)$ be a differentiable function. For some $L_0,L_1>0$,
   $f(x)$ is $(L_0,L_1)$-smooth iff for any $x,y\in\mathbb{R}^d$ with $\|x-y\|\leq 1/L_1$,
  \begin{align}
    \label{def generalized smooth}
  \|\nabla f(x)-\nabla f(y)\|\leq \left(L_0+L_1\nablaf{x}\right)\|x-y\|.
  \end{align}
\end{definition}

In this paper, we denote the set $\{1,\cdots,T\}$ as $[T]$. 
We use $\mathbb{E}_t[\cdot]\triangleq\mathbb{E}[\cdot|z_1,\cdots,z_{t-1}]$ to represent the conditional expectation, where $z_i$ is the random sample in the $i$-th gradient oracle. 
The notation $a\sim \mathcal{O}(b)$ and $a\leq \mathcal{O}(b)$ refer to $c_1 b\leq a\leq c_2 b$ and $a\leq c_3 b$ with $c_1, c_2, c_3$ being positive constants, respectively. 
Also, we write $\tilde{\mathcal{O}}(b)$ as shorthand for $\mathcal{O}(b \cdot \text{poly}(\log b))$.


We consider Problem \eqref{problem} over the Euclidean space $\mathbb{R}^d$ with the $l_2$ norm, denoted as $\|\cdot\|$.


  \item \label{assumption 1} \textbf{Below bounded:} The objective function is bounded from below, i.e.,  $f^*:=\inf_{x\in\mathbb{R}^d}f(x)>-\infty.$
  \item \label{assumption 2}\textbf{Unbiased estimator:} The gradient oracle returns an unbiased estimator of $\nabla f(x)$, i.e., for all $x\in\mathbb{R}^d$, 
  $$\mathbb{E}_z\left[\nabla f_z(x;z)\right]=\nabla f(x).$$
  \item \label{assumption 3}\textbf{Relaxed affine variance (almost-sure version):} The gradient oracle satisfies that for some constants $A,B,C>0$, $$\|\nabla f_z(x;z)-\nabla f(x)\|^2\leq A\left(f(x)-f^*\right)+B\nablaf{x}^2+C \quad a.s., \forall x\in\mathbb{R}^d.$$


\begin{algorithm}[H]
  \caption{Randomized Stochastic Accelerated Gradient (RSAG)}
  \label{algorithm1}
  \begin{algorithmic}[1]
  \Require Horizon $T$, $\tilde{x}_1=x_1\in \mathbb{R}^d$, $\alpha_t \in \left(\left.0,1\right.\right]$, step sizes $\{\theta_t\}_{t\in [T]}$, $\{\gamma_t\}_{t\in [T]}$.
  \For{$t=1,\cdots, T$}
  \State $\overline{x}_t=\alpha_tx_t+\left(1-\alpha_t\right)\tilde{x}_t$;
  \State \textbf{Set} $g_t=\nabla f_z(\overline{x}_t;z_t)$;
  \State $x_{t+1}=x_t-\theta_t g_t$;
  \State $\tilde{x}_{t+1}=\overline{x}_t-\gamma_t g_t$.
  \EndFor
  \end{algorithmic}
\end{algorithm}

For simplicity, we denote $\overline{\Delta}_t=f(\overline{x}_t)-f^*$ and $\xi_t=g_t-\overline{g}_t$ where $\overline{g}_t=\nabla f(\overline{x}_t)$.


\begin{align}
    \label{Gconstant}
    \functiongapboundconstant=\Gconstant.
  \end{align}

