\begin{theorem}
  \label{theorem 1}
  Let  $T>0$ and $\delta\in(0,1)$. Suppose that $f$ is an $\left(L_0,L_1\right)$-smooth function, $\{\overline{x}_t\}_{x\in[T]}$ is a sequence generated by Algorithm \ref{algorithm1} with $\alpha_t=\frac{2}{t+1},\gamma_t=\left(1+\alpha_t\right)\theta_t$ or $\gamma_t=\theta_t$ (SGD), $\forall t\in[T]$, and the step size $\theta_t$ satisfies
  \begin{align}
    \label{eta constant non-convex}
    \theta_t=\eta = \min\left\{\frac{1}{\mathcal{A}\sqrt{T}},\frac{1}{\mathcal{B}},\frac{1}{\mathcal{C}\sqrt{T}}, \frac{1}{\mathcal{G}},\frac{\functiongapboundconstant^{-1/2}}{3\left(A+4BL_0\right)}, \frac{\functiongapboundconstant^{-3/2}}{12BL_1^2}\right\},
  \end{align}
    where $\mathcal{A}, \mathcal{B}, \mathcal{C}, \mathcal{G}$ are defined as
  \begin{align}
    \label{theorem 1 eta}
    \mathcal{A}=4\sqrt{\left(L_0+L_1\mathcal{M}_c\right)A}, \qquad &\mathcal{B}=8\left(L_0+L_1\mathcal{M}_c\right)\left(B+1\right), \notag\\
    \mathcal{C}=2\sqrt{\left(L_0+L_1\mathcal{M}_c\right)C},\qquad &\mathcal{G}=8L_1 \left(\sqrt{A\functiongapboundconstant}+2\left(\sqrt{B}+1\right)\sqrt{L_0 \functiongapboundconstant+L_1^2 \functiongapboundconstant^2}+\sqrt{C}\right),  
  \end{align}
     and $\functiongapboundconstant$, $\mathcal{M}_c$ are given in the following order\footnote{The explicit expressions of $\functiongapboundconstant$ and $\mathcal{M}_c$ are in \eqref{Gconstant} and \eqref{nabla fx_t constant step size}, respectively.},
  \begin{align*} 
  \functiongapboundconstant \sim \mathcal{O}\left(\overline{\Delta}_1+\log^2\frac{T}{\delta}+\frac{\sqrt{C}}{\sqrt{L_0T}}\log\frac{T}{\delta}+\frac{L_0}{L_1^2 }\right), \qquad  \mathcal{M}_c \sim \mathcal{O}\left(L_1\functiongapboundconstant\right).
  \end{align*}
  Under Assumptions \ref{assumption 1}, \ref{assumption 2} and \ref{assumption 3}, with probability at least $1-\delta$, we have\footnote{The detail convergence rate is stated in \eqref{5.34}.}
  \begin{align}
    \label{4.1}
    \frac{1}{T}\sumlimits{t=1}{T}\|\nabla f(\overline{x}_t)\|^2\leq & \mathcal{O}\left(\frac{\functiongapboundconstant\left(\functiongapboundconstant B\log \frac{T}{\delta}+\sqrt{B+1}\right)}{T}+\frac{\sqrt{\functiongapboundconstant}\left(\functiongapboundconstant\sqrt{A}+\sqrt{C}\right)}{\sqrt{T}}\right).
  \end{align}
\end{theorem}

