\begin{proposition}[Proposition 5.2 in \cite{kavis2022high}]
  \label{proposition 1}
  Denote $\alpha_t=\frac{2}{t+1}$ and $\varGamma_t=\left(1-\alpha_t\right)\varGamma_{t-1}$ with $\varGamma_1=1$. We have that for all $t\in[T],$
  \begin{align}
    \label{proposition 1.1}
   \varGamma_{t}\sumlimits{k=1}{t}\frac{\alpha_k}{\varGamma_k}=1,
  \end{align}
  and 
  \begin{align}
    \label{proposition 1.2}
    \left[\sumlimits{k=t}{T}\left(1-\alpha_k\right)\varGamma_k\right]\frac{\alpha_t}{\varGamma_t}\leq 2.
  \end{align}
\end{proposition}

\begin{proposition}
  \label{proposition overline x_t - x_t}
  Let $\{x_t\}_{t\in[T]}$ and $\{\overline{x}_t\}_{t\in[T]}$ be generated by Algorithm \ref{algorithm1}. We have
  \begin{align}
    \label{overline x_t-x_t}
    \overline{x}_t-x_t =\left(1-\alpha_t\right)\varGamma_{t-1}\sumlimits{k=1}{t-1}\frac{\alpha_k}{\varGamma_k}\frac{\left(\theta_k-\gamma_k\right)}{\alpha_k}g_k,
  \end{align}
  and
  \begin{align*}
  \|\overline{x}_t-x_t\|^2\leq \left(1-\alpha_t\right)\varGamma_t\sumlimits{k=1}{t-1}\frac{\alpha_k}{\varGamma_k}\frac{\left(\theta_k-\gamma_k\right)^2}{\alpha_k^2}\|g_k\|^2.
\end{align*}
\end{proposition}

\begin{lemma}
  \label{high probability sum non-convex constant}
  Given $T\geq 1 $ and $\delta\in \left(0,1\right)$, if Assumptions \ref{assumption 2} and \ref{assumption 3} hold, then with probability at least $1-\delta$, $\forall l\in[T]$,
  \begin{align}
    \label{inequality high probability non-convex constant}
    \sumlimits{t=1}{l}-\la\overline{g}_t,\xi_t\ra\leq \frac{1}{4}\sumlimits{t=1}{l}\frac{P_t^2}{P_c^2}\|\overline{g}_t\|^2+3P_c^2\log\frac{T}{\delta},
  \end{align}
  where 
  \begin{align}
    \label{P_t}
    P_t=\sqrt{A\overline{\Delta}_t+4B\left(L_0\overline{\Delta}_t+L_1^2\overline{\Delta}_t^2\right)+C},
  \end{align}
and 
\begin{align}
  \label{P}
  P_c=\sqrt{A\functiongapboundconstant+4B\left(L_0\functiongapboundconstant+L_1^2\functiongapboundconstant^2\right)+C}.
\end{align}
\end{lemma}

\begin{proposition}
  \label{constant bound}
  Under the conditions of Theorem \ref{theorem 1}, $\overline{\Delta}_t\leq \functiongapboundconstant,P_t\leq P_c, \forall t\in[T]$, hold with probability at least $1-\delta$, where  $P_t$, $P_c$ are in \eqref{P_t}, \eqref{P} and $\functiongapboundconstant$ is defined as
  \begin{align}
    \label{Gconstant}
    \functiongapboundconstant=\Gconstant.
  \end{align} 
\end{proposition}

\begin{proof}
  We assume that \eqref{inequality high probability non-convex constant} always happens and then deduce $\overline{\Delta}_t\leq \functiongapboundconstant$, $P_t\leq P_c$ for all $t\in[T]$. 
  Since \eqref{inequality high probability non-convex constant} happens with probability at least $1-\delta$, $\overline{\Delta}_t\leq \functiongapboundconstant$ and $P_t\leq P_c$, $\forall t\in[T]$,  hold with probability at least $1-\delta$. 
  It is obvious that $f(\overline{x}_1)-f^*\leq \functiongapboundconstant$. Therefore, $P_1\leq P_c$.
  Suppose that for some $l\in[T]$, $$f(\overline{x}_t)-f^*\leq \functiongapboundconstant,\quad\forall t\in[l], \quad \text{thus}, \quad P_t\leq P_c, \quad \forall t\in[l].$$ 
  By the triangle inequality of the norm function,
  \begin{align*}
    \|g_t\|\leq  \|g_t-\overline{g}_t\|+\|\overline{g}_t\|
    \leq  \sqrt{A\overline{\Delta}_t+B\|\overline{g}_t\|^2+C}+\|\overline{g}_t\|
    \leq  \sqrt{A\overline{\Delta}_t}+\left(\sqrt{B}+1\right)\|\overline{g}_t\|+\sqrt{C},
  \end{align*}
  where the second inequality follows from Assumption \ref{assumption 3} and the last inequality follows from Lemma \ref{sqrt sum}.
  Combining with Lemma \ref{lemma 6.2} and the assumption that $\overline{\Delta}_t\leq \functiongapboundconstant, \forall t\in[l]$, we have
  \begin{align} 
    \label{g_t}
    \|g_t\| \leq  \sqrt{A\functiongapboundconstant}+2\left(\sqrt{B}+1\right)\sqrt{L_0 \functiongapboundconstant+L_1^2 \functiongapboundconstant^2}+\sqrt{C}, \quad \forall t\in[l].
  \end{align}
  For simplicity, let 
  \begin{align}
    \label{Y_c}
    Y_c=\eta \left(\sqrt{A\functiongapboundconstant}+2\left(\sqrt{B}+1\right)\sqrt{L_0 \functiongapboundconstant+L_1^2 \functiongapboundconstant^2}+\sqrt{C}\right).
  \end{align}
    By the iteration step of Algorithm \ref{algorithm1}, we have
  \begin{align*}
  \|x_{t+1}-x_t\|=\theta_t\|g_t\|=\eta \|g_t\|\leq Y_c\leq 1/8L_1,
  \end{align*}
  where the last inequality follows from the restriction of $\eta$.
 Applying Lemma \ref{descent lemma}, we have 
\begin{align*}
  & f(x_{t+1})-f(x_t) \notag\\
  \leq & \la \nabla f(x_t),x_{t+1}-x_t\ra+\frac{L_0+L_1\nablaf{x_t}}{2}\|x_{t+1}-x_t\|^2\notag\\
   = & -\theta_t\la \nabla f(x_t),g_t\ra+\frac{L_0+L_1\nablaf{x_t}}{2}\theta_t^2\|g_t\|^2\notag\\
   = & -\theta_t\la \overline{g}_t+\nabla f(x_t)-\overline{g}_t,\overline{g}_t+\xi_t\ra + \frac{L_0+L_1\nablaf{x_t}}{2}\theta_t^2\|g_t\|^2\notag\\
   = & -\theta_t \|\overline{g}_t\|^2-\theta_t\la \overline{g}_t,\xi_t\ra -\theta_t \la \nabla f(x_t)-\overline{g}_t,g_t\ra+\frac{L_0+L_1\nablaf{x_t}}{2}\theta_t^2\|g_t\|^2\notag\\
  \leq & -\theta_t \|\overline{g}_t\|^2-\theta_t\la \overline{g}_t,\xi_t\ra +\theta_t \| \nabla f(x_t)-\overline{g}_t\|\|g_t\|+\frac{L_0+L_1\nablaf{x_t}}{2}\theta_t^2\|g_t\|^2,
\end{align*} 
where the first equation follows from the update rule in Algorithm \ref{algorithm1} and the last line follows from Cauchy-Schwarz inequality. 
Recall the constraints of the step size for RSAG with the constant step size and SGD, we have 
\begin{align}
  \label{constant step size constraint}
  0\leq \frac{\gamma_t-\theta_t}{\alpha_t}\leq \theta_t=\eta, \quad \forall t\in[T].
\end{align}
Combining \eqref{overline x_t-x_t} with \eqref{proposition 1.1}, \eqref{g_t}, \eqref{constant step size constraint}, we have
\begin{align}
  \label{bound overline x_t-x_t}
  \|\overline{x}_t-x_t\| \leq & \eta\varGamma_{t-1}\sumlimits{k=1}{t-1}\frac{\alpha_k}{\varGamma_k}\|g_k\|\notag\\
  \leq & \eta\left(\sqrt{A\functiongapboundconstant}+2\left(\sqrt{B}+1\right)\sqrt{L_0 \functiongapboundconstant+L_1^2 \functiongapboundconstant^2}+\sqrt{C}\right)\varGamma_{t-1}\sumlimits{k=1}{t-1}\frac{\alpha_k}{\varGamma_k}\notag\\
  = & Y_c \leq 1/8L_1.
\end{align}
Note that \eqref{bound overline x_t-x_t} holds for all $t\in[l+1]$. 
Thus, applying Definition \ref{definition 1}, we have that for all $t\in[l]$,
\begin{align}  
  \label{inequality base}
  & f(x_{t+1})-f(x_t) \notag\\
  \leq & -\theta_t \|\overline{g}_t\|^2-\theta_t\la \overline{g}_t,\xi_t\ra +\theta_t\left(L_0+L_1\nablaf{x_t}\right)\|\overline{x}_t-x_t\|\|g_t\| +\frac{L_0+L_1\nablaf{x_t}}{2}\theta_t^2\|g_t\|^2\notag\\
  \leq & -\theta_t\|\overline{g}_t\|^2-\theta_t\la\overline{g}_t,\xi_t\ra+\frac{1}{2}\left(L_0+L_1\nablaf{x_t}\right)\|\overline{x}_t-x_t\|^2+\left(L_0+L_1\nablaf{x_t}\right)\theta_t^2\|g_t\|^2\notag\\
  \leq & -\theta_t\|\overline{g}_t\|^2-\theta_t\la\overline{g}_t,\xi_t\ra+\frac{1}{2}\left(L_0+L_1\nablaf{x_t}\right)\left(1-\alpha_t\right)\varGamma_t\sumlimits{k=1}{t}\frac{\alpha_k}{\varGamma_k}\theta_k^2\|g_k\|^2\notag\\
  & + \left(L_0+L_1\nablaf{x_t}\right)\theta_t^2\|g_t\|^2,
\end{align}
where we use Young's inequality in the second inequality and apply Proposition \ref{proposition overline x_t - x_t} with \eqref{constant step size constraint} in the last inequality. 
Summing over $t\in [l]$ with $\theta_t=\eta$, we have
\begin{align}
\label{telescope}
f(x_{l+1})-f(x_1)  \leq& \frac{1}{2}\sum\limits^{l}_{t=1}\left[\lsmooth{t}\left(1-\alpha_t\right)\varGamma_t\sum\limits_{k=1}^t\frac{\alpha_k}{\varGamma_k}\eta^2\|g_k\|^2\right]\notag\\
&+\eta^2\sumlimits{t=1}{l}\lsmooth{t}\|g_t\|^2-\eta\sumlimits{t=1}{l}\|\overline{g}_t\|^2-\eta\sumlimits{t=1}{l}\la \overline{g}_t,\xi_t\ra\notag\\
=& \frac{1}{2}\eta^2 \sumlimits{t=1}{l}\left[\sumlimits{k=t}{l}\lsmooth{k}\left(1-\alpha_k\right)\varGamma_k\right]\frac{\alpha_t}{\varGamma_t}\|g_t\|^2\notag\\
&+\eta^2\sumlimits{t=1}{l}\lsmooth{t}\|g_t\|^2-\eta\sumlimits{t=1}{l}\|\overline{g}_t\|^2-\eta\sumlimits{t=1}{l}\la \overline{g}_t,\xi_t\ra.
\end{align}
Applying the triangle inequality of $\|\cdot\|$, we have that for all $t\in[l]$,
\begin{align}
  \label{nabla fx_t}
  \nablaf{x_t} \leq  \|\overline{g}_t-\nabla f(x_t)\|+\|\overline{g}_t\| 
  \leq  \left(L_0+L_1\|\overline{g}_t\|\right)\|\overline{x}_t-x_t\|+\|\overline{g}_t\|,
\end{align}
where the second inequality holds since $\|\overline{x}_t-x_t\|\leq 1/L_1$. Combining \eqref{bound overline x_t-x_t} and \eqref{nabla fx_t}, for all $t\in[l]$,
\begin{align}
  \label{nabla fx_t constant step size}
   \nablaf{x_t}
  \leq & \frac{1}{8L_1}\left(L_0+2L_1\sqrt{L_0\functiongapboundconstant+L_1^2\functiongapboundconstant^2}\right)+2\sqrt{L_0 \functiongapboundconstant+L_1^2 \functiongapboundconstant^2}\notag\\
  = & \frac{L_0}{8L_1}+\frac{9}{4} \sqrt{L_0 \functiongapboundconstant+L_1^2 \functiongapboundconstant^2}=\mathcal{M}_c,
\end{align}
where we apply Lemma \ref{lemma 6.2} to the inequality. 
Applying the triangle inequality again, we have
\begin{align}
  \label{triangle square}
  \|g_t\|^2\leq 2\|g_t-\overline{g}_t\|^2+2\|\overline{g}_t\|^2\leq 2\left(A \overline{\Delta}_t+\left(B+1\right)\|\overline{g}_t\|^2+C\right).
\end{align}
Combining  \eqref{proposition 1.2}, \eqref{inequality high probability non-convex constant}, \eqref{telescope} and \eqref{triangle square}, together with the bound of $\nablaf{x_t}$ in \eqref{nabla fx_t constant step size}, we have 
\begin{align}
  \label{4.26}
f(x_{l+1})-f(x_1)  \leq & 2\left(L_0+L_1\mathcal{M}_c\right)\eta^2\sumlimits{t=1}{l}\|g_t\|^2-\eta\sumlimits{t=1}{l}\|\overline{g}_t\|^2-\eta\sumlimits{t=1}{l}\la\overline{g}_t,\xi_t\ra\notag\\
\leq & 4\left(L_0+L_1\mathcal{M}_c\right)\eta^2\sumlimits{t=1}{l}\left(A\overline{\Delta}_t+\left(B+1\right)\|\overline{g}_t\|^2+C\right)-\eta\sumlimits{t=1}{l}\|\overline{g}_t\|^2\notag\\
&+\frac{1}{4}\eta\sumlimits{t=1}{l}\frac{P_t^2}{P_c^2}\|\overline{g}_t\|^2+3\eta P_c^2\log\frac{T}{\delta}\notag\\
\leq & 4\left(L_0+L_1\mathcal{M}_c\right)\eta^2 lA\functiongapboundconstant+4\left(L_0+L_1\mathcal{M}_c\right)\eta^2lC \notag\\
&+\left(4\left(L_0+L_1\mathcal{M}_c\right)\eta\left(B+1\right)+\frac{1}{4}-1\right)\eta\sumlimits{t=1}{l}\|\overline{g}_t\|^2+3\eta P_c^2\log\frac{T}{\delta},
\end{align}
where the last inequality holds since the assumption that $P_t\leq P_c, \forall t\in[l]$. 
Applying the restrictions of $\eta$ in \eqref{eta constant non-convex}, it is apparent that 
\begin{align*}
  f(x_{l+1})\leq f(x_1)+\frac{1}{4}\functiongapboundconstant+1+3\eta P_c^2\log\frac{T}{\delta}.
\end{align*}
