\begin{lemma}[Remark 2.3 in \cite{zhang2020improved}]
  \label{descent lemma}
  Suppose that $f:\mathbb{R}^d \rightarrow \mathbb{R}$ is an $(L_0,L_1)$-generalized smooth function. When $\|x-y\|\leq 1/L_1$, we have 
  $$\left\lvert f(y)- f(x)-\la \nabla f(x),y-x\ra\right\rvert \leq \frac{L_0+L_1\nablaf{x}}{2}\|x-y\|^2.$$
\end{lemma}

\begin{lemma}[Lemma 1 in \cite{li2020high}]
  \label{lemma high probability}
  Assume that $\{Z_t\}_{t\in[T]}$ is a martingale difference sequence with respect to $\gamma_1, \gamma_2, \cdots, \gamma_T$ and $\mathbb{E}_t[\exp\left(Z_t^2/\sigma_t^2\right)]\leq \exp(1)$ for all $1 \leq t \leq T$, where $\sigma_t$ is a sequence of measurable random variables with respect to $\gamma_1, \gamma_2, \cdots, \gamma_{t-1}$. Then, for any fixed $\lambda >0$ and $\delta\in(0,1)$, with probability at least $1-\delta$, we have
  $$\sumlimits{t=1}{T}Z_t\leq \frac{3\lambda}{4}\sumlimits{t=1}{T}\sigma_t^2+\frac{1}{\lambda}\log\frac{1}{\delta}.$$
\end{lemma}

\begin{lemma}
  \label{lemma 6.2}  
  Let $f(x) : \mathbb{R}^d\rightarrow \mathbb{R}$ be an $(L_0,L_1)$-smooth function with minimum $f^*$. 
  Then, $$\|\nabla f(x_t)\|^2\leq 2\left(L_0+L_1\|\nabla f(x_t)\|\right)\Delta_t,$$ and $$\nablaf{x_t}^2\leq 4L_0\Delta_t+4L_1^2\Delta_t^2,$$
  where $\Delta_t=f(x_t)-f^*$.
  \end{lemma}

\begin{proof}
    Let $x=x_t-\frac{1}{L_0+L_1\|\nabla f(x_t)\|}\nabla f(x_t)$.
    It is easy to verify that $\|x-x_t\|\leq 1/L_1$.
    From Lemma \ref{descent lemma}, we have that
    $$f(x) \leq f(x_t)  + \la \nabla f(x_t), x - x_t \ra + {L_0+L_1 \|\nabla f(x)\|  \over 2} \|x - x_t\|^2.$$
    Hence, 
    \begin{align*}
      &\frac{\|\nabla f(x_t)\|^2}{2\left(L_0+L_1\|\nabla f(x_t)\|\right)}\leq f(x_t)-f(x)\leq \Delta_t.
    \end{align*}
  Re-arranging the above inequality and applying Cauchy-Schwarz inequality and Young's inequality, we have
  \begin{align*}
    \nablaf{x_{t}}^2 \leq & 2L_0\Delta_{t}+\frac{1}{2}\|\nabla f(x_{t})\|^2+2L_1^2\Delta_{t}^2.
  \end{align*}
  We obtain the desired result.
  \end{proof}

