    By the iteration step of Algorithm \ref{algorithm1}, we have
  \begin{align*}
  \|x_{t+1}-x_t\|=\theta_t\|g_t\|=\eta \|g_t\|\leq Y_c\leq 1/8L_1,
  \end{align*}
  where the last inequality follows from the restriction of $\eta$.
 Applying Lemma \ref{descent lemma}, we have 
\begin{align*}
  & f(x_{t+1})-f(x_t) \notag\\
  \leq & \la \nabla f(x_t),x_{t+1}-x_t\ra+\frac{L_0+L_1\nablaf{x_t}}{2}\|x_{t+1}-x_t\|^2\notag\\
   = & -\theta_t\la \nabla f(x_t),g_t\ra+\frac{L_0+L_1\nablaf{x_t}}{2}\theta_t^2\|g_t\|^2\notag\\
   = & -\theta_t\la \overline{g}_t+\nabla f(x_t)-\overline{g}_t,\overline{g}_t+\xi_t\ra + \frac{L_0+L_1\nablaf{x_t}}{2}\theta_t^2\|g_t\|^2\notag\\
   = & -\theta_t \|\overline{g}_t\|^2-\theta_t\la \overline{g}_t,\xi_t\ra -\theta_t \la \nabla f(x_t)-\overline{g}_t,g_t\ra+\frac{L_0+L_1\nablaf{x_t}}{2}\theta_t^2\|g_t\|^2\notag\\
  \leq & -\theta_t \|\overline{g}_t\|^2-\theta_t\la \overline{g}_t,\xi_t\ra +\theta_t \| \nabla f(x_t)-\overline{g}_t\|\|g_t\|+\frac{L_0+L_1\nablaf{x_t}}{2}\theta_t^2\|g_t\|^2,
\end{align*} 
where the first equation follows from the update rule in Algorithm \ref{algorithm1} and the last line follows from Cauchy-Schwarz inequality. 
Recall the constraints of the step size for RSAG with the constant step size and SGD, we have 
\begin{align}
  \label{constant step size constraint}
  0\leq \frac{\gamma_t-\theta_t}{\alpha_t}\leq \theta_t=\eta, \quad \forall t\in[T].
\end{align}
Combining \eqref{overline x_t-x_t} with \eqref{proposition 1.1}, \eqref{g_t}, \eqref{constant step size constraint}, we have
\begin{align}
  \label{bound overline x_t-x_t}
  \|\overline{x}_t-x_t\| \leq & \eta\varGamma_{t-1}\sumlimits{k=1}{t-1}\frac{\alpha_k}{\varGamma_k}\|g_k\|\notag\\
  \leq & \eta\left(\sqrt{A\functiongapboundconstant}+2\left(\sqrt{B}+1\right)\sqrt{L_0 \functiongapboundconstant+L_1^2 \functiongapboundconstant^2}+\sqrt{C}\right)\varGamma_{t-1}\sumlimits{k=1}{t-1}\frac{\alpha_k}{\varGamma_k}\notag\\
  = & Y_c \leq 1/8L_1.
\end{align}
Note that \eqref{bound overline x_t-x_t} holds for all $t\in[l+1]$. 
Thus, applying Definition \ref{definition 1}, we have that for all $t\in[l]$,
\begin{align}  
  \label{inequality base}
  & f(x_{t+1})-f(x_t) \notag\\
  \leq & -\theta_t \|\overline{g}_t\|^2-\theta_t\la \overline{g}_t,\xi_t\ra +\theta_t\left(L_0+L_1\nablaf{x_t}\right)\|\overline{x}_t-x_t\|\|g_t\| +\frac{L_0+L_1\nablaf{x_t}}{2}\theta_t^2\|g_t\|^2\notag\\
  \leq & -\theta_t\|\overline{g}_t\|^2-\theta_t\la\overline{g}_t,\xi_t\ra+\frac{1}{2}\left(L_0+L_1\nablaf{x_t}\right)\|\overline{x}_t-x_t\|^2+\left(L_0+L_1\nablaf{x_t}\right)\theta_t^2\|g_t\|^2\notag\\
  \leq & -\theta_t\|\overline{g}_t\|^2-\theta_t\la\overline{g}_t,\xi_t\ra+\frac{1}{2}\left(L_0+L_1\nablaf{x_t}\right)\left(1-\alpha_t\right)\varGamma_t\sumlimits{k=1}{t}\frac{\alpha_k}{\varGamma_k}\theta_k^2\|g_k\|^2\notag\\
  & + \left(L_0+L_1\nablaf{x_t}\right)\theta_t^2\|g_t\|^2,
\end{align}
where we use Young's inequality in the second inequality and apply Proposition \ref{proposition overline x_t - x_t} with \eqref{constant step size constraint} in the last inequality. 
Summing over $t\in [l]$ with $\theta_t=\eta$, we have
\begin{align}
\label{telescope}
f(x_{l+1})-f(x_1)  \leq& \frac{1}{2}\sum\limits^{l}_{t=1}\left[\lsmooth{t}\left(1-\alpha_t\right)\varGamma_t\sum\limits_{k=1}^t\frac{\alpha_k}{\varGamma_k}\eta^2\|g_k\|^2\right]\notag\\
&+\eta^2\sumlimits{t=1}{l}\lsmooth{t}\|g_t\|^2-\eta\sumlimits{t=1}{l}\|\overline{g}_t\|^2-\eta\sumlimits{t=1}{l}\la \overline{g}_t,\xi_t\ra\notag\\
=& \frac{1}{2}\eta^2 \sumlimits{t=1}{l}\left[\sumlimits{k=t}{l}\lsmooth{k}\left(1-\alpha_k\right)\varGamma_k\right]\frac{\alpha_t}{\varGamma_t}\|g_t\|^2\notag\\
&+\eta^2\sumlimits{t=1}{l}\lsmooth{t}\|g_t\|^2-\eta\sumlimits{t=1}{l}\|\overline{g}_t\|^2-\eta\sumlimits{t=1}{l}\la \overline{g}_t,\xi_t\ra.
\end{align}
Applying the triangle inequality of $\|\cdot\|$, we have that for all $t\in[l]$,
\begin{align}
  \label{nabla fx_t}
  \nablaf{x_t} \leq  \|\overline{g}_t-\nabla f(x_t)\|+\|\overline{g}_t\| 
  \leq  \left(L_0+L_1\|\overline{g}_t\|\right)\|\overline{x}_t-x_t\|+\|\overline{g}_t\|,
\end{align}
where the second inequality holds since $\|\overline{x}_t-x_t\|\leq 1/L_1$. Combining \eqref{bound overline x_t-x_t} and \eqref{nabla fx_t}, for all $t\in[l]$,
\begin{align}
  \label{nabla fx_t constant step size}
   \nablaf{x_t}
  \leq & \frac{1}{8L_1}\left(L_0+2L_1\sqrt{L_0\functiongapboundconstant+L_1^2\functiongapboundconstant^2}\right)+2\sqrt{L_0 \functiongapboundconstant+L_1^2 \functiongapboundconstant^2}\notag\\
  = & \frac{L_0}{8L_1}+\frac{9}{4} \sqrt{L_0 \functiongapboundconstant+L_1^2 \functiongapboundconstant^2}=\mathcal{M}_c,
\end{align}
where we apply Lemma \ref{lemma 6.2} to the inequality. 
Applying the triangle inequality again, we have
\begin{align}
  \label{triangle square}
  \|g_t\|^2\leq 2\|g_t-\overline{g}_t\|^2+2\|\overline{g}_t\|^2\leq 2\left(A \overline{\Delta}_t+\left(B+1\right)\|\overline{g}_t\|^2+C\right).
\end{align}
Combining  \eqref{proposition 1.2}, \eqref{inequality high probability non-convex constant}, \eqref{telescope} and \eqref{triangle square}, together with the bound of $\nablaf{x_t}$ in \eqref{nabla fx_t constant step size}, we have 
\begin{align}
  \label{4.26}
f(x_{l+1})-f(x_1)  \leq & 2\left(L_0+L_1\mathcal{M}_c\right)\eta^2\sumlimits{t=1}{l}\|g_t\|^2-\eta\sumlimits{t=1}{l}\|\overline{g}_t\|^2-\eta\sumlimits{t=1}{l}\la\overline{g}_t,\xi_t\ra\notag\\
\leq & 4\left(L_0+L_1\mathcal{M}_c\right)\eta^2\sumlimits{t=1}{l}\left(A\overline{\Delta}_t+\left(B+1\right)\|\overline{g}_t\|^2+C\right)-\eta\sumlimits{t=1}{l}\|\overline{g}_t\|^2\notag\\
&+\frac{1}{4}\eta\sumlimits{t=1}{l}\frac{P_t^2}{P_c^2}\|\overline{g}_t\|^2+3\eta P_c^2\log\frac{T}{\delta}\notag\\
\leq & 4\left(L_0+L_1\mathcal{M}_c\right)\eta^2 lA\functiongapboundconstant+4\left(L_0+L_1\mathcal{M}_c\right)\eta^2lC \notag\\
&+\left(4\left(L_0+L_1\mathcal{M}_c\right)\eta\left(B+1\right)+\frac{1}{4}-1\right)\eta\sumlimits{t=1}{l}\|\overline{g}_t\|^2+3\eta P_c^2\log\frac{T}{\delta},
\end{align}
where the last inequality holds since the assumption that $P_t\leq P_c, \forall t\in[l]$. 
Applying the restrictions of $\eta$ in \eqref{eta constant non-convex}, it is apparent that 
\begin{align*}
  f(x_{l+1})\leq f(x_1)+\frac{1}{4}\functiongapboundconstant+1+3\eta P_c^2\log\frac{T}{\delta}.
\end{align*}
Since $P_c^2 = A\functiongapboundconstant+4B\left(L_0\functiongapboundconstant+L_1^2\functiongapboundconstant^2\right)+C= \left(A+4BL_0\right)\functiongapboundconstant+4BL_1^2\functiongapboundconstant^2+C$,
\begin{align}
  \label{f x+1-f x_1 constant step size}
  f(x_{l+1}) \leq & f(x_1)+\frac{1}{4}\functiongapboundconstant+1+3\eta \left(A+4BL_0\right)\functiongapboundconstant\log\frac{T}{\delta}+12\eta BL_1^2\functiongapboundconstant^2\log\frac{T}{\delta}+3\eta C \log\frac{T}{\delta}\notag\\
  \leq & f(x_1)+\frac{1}{4}\functiongapboundconstant+1+2\sqrt{\functiongapboundconstant}\log\frac{T}{\delta}+3\eta C\log\frac{T}{\delta}     \notag\\
  \leq & f(x_1)+\frac{1}{2}\functiongapboundconstant+1+ 4\log^2\frac{T}{\delta}+3\eta C \log\frac{T}{\delta},
\end{align}
where the second inequality is due to the restrictions of $\eta$ in \eqref{eta constant non-convex} and the last inequality follows from Young's inequality. Next we will bound the gap between $f(x_{l+1})$ and $f(\overline{x}_{l+1})$. By \eqref{bound overline x_t-x_t}, we have $\|\overline{x}_{l+1}-x_{l+1}\|<1/L_1$. Using Lemma \ref{descent lemma} again,
\begin{align}
  \label{gap between f overline x_t+1 and f x_t+1 constant step size}
  f(\overline{x}_{l+1}) \leq & f(x_{l+1})+\la \overline{g}_{l+1}, \overline{x}_{l+1}-x_{l+1}\ra+\frac{L_0+L_1\|\overline{g}_{l+1}\|}{2}\|\overline{x}_{l+1}-x_{l+1}\|^2\notag\\
  \leq & f(x_{l+1})+\|\overline{g}_{l+1}\|\|\overline{x}_{l+1}-x_{l+1}\|+\frac{L_0+L_1\|\overline{g}_{l+1}\|}{2}\|\overline{x}_{l+1}-x_{l+1}\|^2,
\end{align}
where the second inequality follows from Cauchy-Schwarz inequality. Substituting \eqref{bound overline x_t-x_t} into \eqref{gap between f overline x_t+1 and f x_t+1 constant step size}, we have
\begin{align}
  \label{descent lemma 2}
  f(\overline{x}_{l+1}) \leq & f(x_{l+1})+\frac{1}{8L_1}\|\overline{g}_{l+1}\|+\frac{1}{128L_1^2}\left(L_0+L_1\|\overline{g}_{l+1}\|\right)\notag\\
  = & f(x_{l+1})+\frac{17}{128L_1}\|\overline{g}_{l+1}\|+\frac{L_0}{128L_1^2}.
\end{align}
Combining \eqref{f x+1-f x_1 constant step size} and \eqref{descent lemma 2}, and subtracting $f^*$ from both sides, we have
\begin{align}
  \overline{\Delta}_{l+1}\leq & \overline{\Delta}_1+\frac{1}{2}\functiongapboundconstant+1+4\log^2\frac{T}{\delta}+3\eta C \log\frac{T}{\delta} +\frac{17}{128L_1}\|\overline{g}_{l+1}\|+\frac{L_0}{128L_1^2}\notag\\
  \leq & \overline{\Delta}_1+\frac{1}{2}\functiongapboundconstant+1+4\log^2\frac{T}{\delta}+3\eta C \log\frac{T}{\delta} + \frac{17}{64L_1}\left(\sqrt{L_0\overline{\Delta}_{l+1}}+L_1\overline{\Delta}_{l+1}\right)+  \frac{L_0}{128L_1^2}\notag\\
  \leq &   \overline{\Delta}_1+\frac{1}{2}\functiongapboundconstant+1+4\log^2\frac{T}{\delta}+\frac{\sqrt{2C}}{\sqrt{L_0T}}\log\frac{T}{\delta} + \frac{7}{64}\overline{\Delta}_{l+1}+\frac{289L_0}{1792L_1^2}+\frac{17}{64}\overline{\Delta}_{l+1}+\frac{L_0}{128L_1^2}.
\end{align}
The second inequality follows from Lemma \ref{lemma 6.2} and Lemma \ref{sqrt sum}. The third inequality follows from Young's inequality and the constraint of $\eta$ that $\eta\leq \frac{1}{2\sqrt{\left(L_0+L_1\mathcal{M}_c\right)CT}}$, where $\mathcal{M}_c\geq \frac{L_0}{8L_1}$.
Re-arranging the above inequality, we have 
\begin{align*}
  \frac{5}{8}\overline{\Delta}_{l+1}\leq \overline{\Delta}_1+\frac{1}{2}\functiongapboundconstant+1+4\log^2\frac{T}{\delta}+\frac{\sqrt{2C}}{\sqrt{L_0T}}+\frac{303L_0}{1792L_1^2}\leq \frac{5}{8}\functiongapboundconstant.
\end{align*}
The second inequality holds since 
$\functiongapboundconstant=\Gconstant$.
Therefore, $P_{l+1}\leq P_c$ also holds. 
So the induction is complete and we obtain the desired result. 
\end{proof}

\begin{proof}[Proof of Theorem \ref{theorem 1}]
We assume \eqref{inequality high probability non-convex constant} always holds then we deduce \eqref{4.1}. Note that \eqref{inequality high probability non-convex constant} holds with probability at least $1-\delta$. Therefore, \eqref{4.1} holds with probability at least $1-\delta$.
Recalling \eqref{inequality base} and dividing $\theta_t$ on both sides, we have  
\begin{align*}
  \|\overline{g}_t\|^2\leq &\frac{f(x_t)-f(x_{t+1})}{\theta_t}+\frac{1}{2\theta_t}\left(L_0+L_1\nablaf{x_t}\right)\left(1-\alpha_t\right)\varGamma_t\sumlimits{k=1}{t}\frac{\alpha_k}{\varGamma_k}\theta_k^2\|g_k\|^2\notag\\
&+\left(L_0+L_1\nablaf{x_t}\right)\theta_t\|g_t\|^2-\la\overline{g}_t,\xi_t\ra.
\end{align*}
Summing over $t\in[T]$ with $\theta_t=\eta$,
\begin{align}
  \label{constant gt}
  \sumlimits{t=1}{T}\|\overline{g}_t\|^2\leq & \frac{1}{\eta}\sumlimits{t=1}{T}\left(f(x_t)-f(x_{t+1})\right)+\frac{\eta}{2}\sumlimits{t=1}{T}\left[\left(L_0+L_1\nablaf{x_t}\right)\left(1-\alpha_t\right)\varGamma_t\sumlimits{k=1}{t}\frac{\alpha_k}{\varGamma_k}\|g_k\|^2\right]\notag\\
  &+\eta\sumlimits{t=1}{T}\left(L_0+L_1\nablaf{x_t}\right)\|g_t\|^2-\sumlimits{t=1}{T}\la \overline{g}_t,\xi_t\ra\notag\\
  \leq &\frac{\overline{\Delta}_1}{\eta}+\frac{\eta}{2} \sumlimits{t=1}{T}\left[\sumlimits{k=t}{T}\lsmooth{k}\left(1-\alpha_k\right)\varGamma_k\right]\frac{\alpha_t}{\varGamma_t}\|g_t\|^2\notag\\
  & +\eta\sumlimits{t=1}{T}\left(L_0+L_1\nablaf{x_t}\right)\|g_t\|^2-\sumlimits{t=1}{T}\la \overline{g}_t,\xi_t\ra.
\end{align}
Applying Lemma \ref{high probability sum non-convex constant},
\begin{align*}
  \sumlimits{t=1}{T}\|\overline{g}_t\|^2\leq &\frac{\overline{\Delta}_1}{\eta}+\frac{\eta}{2} \sumlimits{t=1}{T}\left[\sumlimits{k=t}{T}\lsmooth{k}\left(1-\alpha_k\right)\varGamma_k\right]\frac{\alpha_t}{\varGamma_t}\|g_t\|^2\notag\\
  & +\eta\sumlimits{t=1}{T}\left(L_0+L_1\nablaf{x_t}\right)\|g_t\|^2+\frac{1}{4P_c^2}\sumlimits{t=1}{T}\|\overline{g}_t\|^2 P_t^2+3P_c^2\log\frac{T}{\delta}.
\end{align*}
Combining with \eqref{proposition 1.2}, \eqref{nabla fx_t constant step size}, \eqref{triangle square} and Proposition \ref{constant bound}, we have
\begin{align*}
  \sumlimits{t=1}{T}\|\overline{g}_t\|^2 \leq & \frac{\overline{\Delta}_1}{\eta}+2\eta\sumlimits{t=1}{T}\left(L_0+L_1\mathcal{M}_c\right)\|g_t\|^2+\frac{1}{4}\sumlimits{t=1}{T}\|\overline{g}_t\|^2+3P_c^2\log\frac{T}{\delta}\notag\\
  \leq & \frac{\overline{\Delta}_1}{\eta}+4\eta\left(L_0+L_1\mathcal{M}_c\right) T \left(A\functiongapboundconstant+C\right)+4\left(L_0+L_1\mathcal{M}_c\right)\left(B+1\right)\eta\sumlimits{t=1}{T}\|\overline{g}_t\|^2\notag\\
  & + \frac{1}{4}\sumlimits{t=1}{T}\|\overline{g}_t\|^2+3\left(A\functiongapboundconstant + 4B\left(L_0\functiongapboundconstant+L_1^2\functiongapboundconstant^2\right)+C\right)\log\frac{T}{\delta}.
\end{align*}
Re-arranging the above inequality with the constraint of $\eta$ in \eqref{eta constant non-convex}, we obtain 
\begin{align*}
  \frac{1}{T}\sumlimits{t=1}{T}\|\overline{g}_t\|^2\leq & \frac{4\overline{\Delta}_1}{\eta T}+ \frac{4}{\sqrt{T}}\sqrt{L_0+L_1\mathcal{M}_c}\left(\sqrt{A\functiongapboundconstant^2}+2\sqrt{C}\right)\notag\\
  &+\frac{12}{T}\left(A\functiongapboundconstant + 4B\left(L_0\functiongapboundconstant+L_1^2\functiongapboundconstant^2\right)+C\right)\log\frac{T}{\delta}.
\end{align*}
Combining with the restrictions of $\eta$ in \eqref{eta constant non-convex} again, we get the final result,
\begin{align}
  \label{5.34}
  \frac{1}{T}\sumlimits{t=1}{T}\|\overline{g}_t\|^2\leq & \frac{4}{\sqrt{T}}\sqrt{L_0+L_1\mathcal{M}_c}\left(\sqrt{A}\left(\functiongapboundconstant+4\overline{\Delta}_1\right)+2\sqrt{C}\left(1+\overline{\Delta}_1\right)\right)\notag\\
  &+ \frac{32\overline{\Delta}_1}{T}\left(L_0+L_1\mathcal{M}_c\right)\left(B+1\right) +  \frac{12\overline{\Delta}_1}{T}\left(\left(A+4BL_0\right)\functiongapboundconstant^{1/2}+4BL_1^2\functiongapboundconstant^{3/2}\right) \notag\\
  &+ \frac{32\overline{\Delta}_1}{T}L_1 \left(\sqrt{A\functiongapboundconstant}+2\left(\sqrt{B}+1\right)\sqrt{L_0 \functiongapboundconstant+L_1^2 \functiongapboundconstant^2}+\sqrt{C}\right) \notag\\
  &+\frac{12}{T}\left(A\functiongapboundconstant + 4B\left(L_0\functiongapboundconstant+L_1^2\functiongapboundconstant^2\right)+C\right)\log\frac{T}{\delta}.
\end{align}
\end{proof}

\begin{lemma}[Remark 2.3 in \cite{zhang2020improved}]
  \label{descent lemma}
  Suppose that $f:\mathbb{R}^d \rightarrow \mathbb{R}$ is an $(L_0,L_1)$-generalized smooth function. When $\|x-y\|\leq 1/L_1$, we have 
  $$\left\lvert f(y)- f(x)-\la \nabla f(x),y-x\ra\right\rvert \leq \frac{L_0+L_1\nablaf{x}}{2}\|x-y\|^2.$$
\end{lemma}

\begin{lemma}[Lemma 1 in \cite{li2020high}]
  \label{lemma high probability}
  Assume that $\{Z_t\}_{t\in[T]}$ is a martingale difference sequence with respect to $\gamma_1, \gamma_2, \cdots, \gamma_T$ and $\mathbb{E}_t[\exp\left(Z_t^2/\sigma_t^2\right)]\leq \exp(1)$ for all $1 \leq t \leq T$, where $\sigma_t$ is a sequence of measurable random variables with respect to $\gamma_1, \gamma_2, \cdots, \gamma_{t-1}$. Then, for any fixed $\lambda >0$ and $\delta\in(0,1)$, with probability at least $1-\delta$, we have
  $$\sumlimits{t=1}{T}Z_t\leq \frac{3\lambda}{4}\sumlimits{t=1}{T}\sigma_t^2+\frac{1}{\lambda}\log\frac{1}{\delta}.$$
\end{lemma}

\begin{lemma}
  \label{lemma 6.2}  
  Let $f(x) : \mathbb{R}^d\rightarrow \mathbb{R}$ be an $(L_0,L_1)$-smooth function with minimum $f^*$. 
  Then, $$\|\nabla f(x_t)\|^2\leq 2\left(L_0+L_1\|\nabla f(x_t)\|\right)\Delta_t,$$ and $$\nablaf{x_t}^2\leq 4L_0\Delta_t+4L_1^2\Delta_t^2,$$
  where $\Delta_t=f(x_t)-f^*$.
  \end{lemma}

\begin{proof}
    Let $x=x_t-\frac{1}{L_0+L_1\|\nabla f(x_t)\|}\nabla f(x_t)$.
    It is easy to verify that $\|x-x_t\|\leq 1/L_1$.
    From Lemma \ref{descent lemma}, we have that
    $$f(x) \leq f(x_t)  + \la \nabla f(x_t), x - x_t \ra + {L_0+L_1 \|\nabla f(x)\|  \over 2} \|x - x_t\|^2.$$
    Hence, 
    \begin{align*}
      &\frac{\|\nabla f(x_t)\|^2}{2\left(L_0+L_1\|\nabla f(x_t)\|\right)}\leq f(x_t)-f(x)\leq \Delta_t.
    \end{align*}
  Re-arranging the above inequality and applying Cauchy-Schwarz inequality and Young's inequality, we have
  \begin{align*}
    \nablaf{x_{t}}^2 \leq & 2L_0\Delta_{t}+\frac{1}{2}\|\nabla f(x_{t})\|^2+2L_1^2\Delta_{t}^2.
  \end{align*}
  We obtain the desired result.
  \end{proof}

\begin{lemma}
    \label{sqrt sum}
    Let $\{a_t\}_{t\in[n]}$ be a sequence of non-negative real numbers. We have
    \begin{align*}
      \sqrt{\sum_{i=1}^n a_i}\leq \sumlimits{i=1}{n}\sqrt{a_i}.
    \end{align*}
  \end{lemma}

\begin{proof}[Proof of Proposition \ref{proposition 1}]
  From \cite{ghadimi2016accelerated}, we have
  \begin{align*}
    \sumlimits{k=1}{t}\frac{\alpha_k}{\varGamma_k}=\frac{\alpha_1}{\varGamma_1}+\sumlimits{k=2}{t}\frac{\alpha_k}{\varGamma_k}=\frac{1}{\varGamma_1}+\sumlimits{k=2}{t}\frac{1}{\varGamma_k}\left(1-\frac{\varGamma_{k}}{\varGamma_{k-1}}\right)=\frac{1}{\varGamma_1}+\sumlimits{k=2}{t}\left(\frac{1}{\varGamma_k}-\frac{1}{\varGamma_{k-1}}\right)=\frac{1}{\varGamma_t}.
  \end{align*}
  Therefore, 
  \begin{align*}
    \varGamma_{t}\sumlimits{k=1}{t}\frac{\alpha_k}{\varGamma_k}=1.
  \end{align*}
  For any $t\geq 2$, we have
 \begin{align*}
  \varGamma_t=\left(1-\alpha_t\right)\varGamma_{t-1}=\frac{t-1}{t+1}\varGamma_{t-1}=\cdots=\frac{t-1}{t+1}\cdot\frac{t-2}{t}\cdots \frac{2-1}{2+1}=\frac{2}{t\left(t+1\right)}.
\end{align*}
Hence,
  \begin{align*}
    \left[\sumlimits{k=t}{T}\left(1-\alpha_k\right)\varGamma_k\right]\frac{\alpha_t}{\varGamma_t} & =\left[\sumlimits{k=t}{T}\frac{k-1}{k+1}\frac{2}{k\left(k+1\right)}\right]\cdot t\notag\\
    \leq & 2t \sumlimits{k=t}{T}\frac{1}{k\left(k+1\right)}\notag\\
    = & 2t\left(\frac{1}{t}-\frac{1}{T+1}\right) \leq 2.
  \end{align*}
\end{proof}

\begin{proof}[Proof of Proposition \ref{proposition overline x_t - x_t}]
  Following from the iteration steps in Algorithm \ref{algorithm1} and referring to the proof in \cite{ghadimi2016accelerated}, we have 
  \begin{align*}
    \overline{x}_t-x_t = & \left(1-\alpha_t\right)[\tilde{x}_t-x_t]\notag\\
    = & \left(1-\alpha_t\right)[\overline{x}_{t-1}-x_{t-1}+\left(\theta_{t-1}-\gamma_{t-1}\right)g_{t-1}]\notag\\
    = & \left(1-\alpha_t\right)[\left(1-\alpha_{t-1}\right)\left(\tilde{x}_{t-1}-x_{t-1}\right)+\left(\theta_{t-1}-\gamma_{t-1}\right)g_{t-1}]\notag\\
    = & \left(1-\alpha_t\right)\sumlimits{k=1}{t-1}\left(\prod\limits_{j=k+1}^{t-1}\left(1-\alpha_j\right)\right)\left(\theta_k-\gamma_k\right)g_k\notag\\
    = & \left(1-\alpha_t\right)\sumlimits{k=1}{t-1}\frac{\varGamma_{t-1}}{\varGamma_{k}}\left(\theta_k-\gamma_k\right)g_k\notag\\
