  f(x_{l+1}) \leq & f(x_1)+\frac{1}{4}\functiongapboundconstant+1+3\eta \left(A+4BL_0\right)\functiongapboundconstant\log\frac{T}{\delta}+12\eta BL_1^2\functiongapboundconstant^2\log\frac{T}{\delta}+3\eta C \log\frac{T}{\delta}\notag\\
  \leq & f(x_1)+\frac{1}{4}\functiongapboundconstant+1+2\sqrt{\functiongapboundconstant}\log\frac{T}{\delta}+3\eta C\log\frac{T}{\delta}     \notag\\
  \leq & f(x_1)+\frac{1}{2}\functiongapboundconstant+1+ 4\log^2\frac{T}{\delta}+3\eta C \log\frac{T}{\delta},
\end{align}

where the second inequality is due to the restrictions of $\eta$ in \eqref{eta constant non-convex} and the last inequality follows from Young's inequality. Next we will bound the gap between $f(x_{l+1})$ and $f(\overline{x}_{l+1})$. By \eqref{bound overline x_t-x_t}, we have $\|\overline{x}_{l+1}-x_{l+1}\|<1/L_1$. Using Lemma \ref{descent lemma} again,
\begin{align}
  \label{gap between f overline x_t+1 and f x_t+1 constant step size}
  f(\overline{x}_{l+1}) \leq & f(x_{l+1})+\la \overline{g}_{l+1}, \overline{x}_{l+1}-x_{l+1}\ra+\frac{L_0+L_1\|\overline{g}_{l+1}\|}{2}\|\overline{x}_{l+1}-x_{l+1}\|^2\notag\\
  \leq & f(x_{l+1})+\|\overline{g}_{l+1}\|\|\overline{x}_{l+1}-x_{l+1}\|+\frac{L_0+L_1\|\overline{g}_{l+1}\|}{2}\|\overline{x}_{l+1}-x_{l+1}\|^2,
\end{align}
where the second inequality follows from Cauchy-Schwarz inequality. Substituting \eqref{bound overline x_t-x_t} into \eqref{gap between f overline x_t+1 and f x_t+1 constant step size}, we have

\begin{align}
  \label{descent lemma 2}
  f(\overline{x}_{l+1}) \leq & f(x_{l+1})+\frac{1}{8L_1}\|\overline{g}_{l+1}\|+\frac{1}{128L_1^2}\left(L_0+L_1\|\overline{g}_{l+1}\|\right)\notag\\
  = & f(x_{l+1})+\frac{17}{128L_1}\|\overline{g}_{l+1}\|+\frac{L_0}{128L_1^2}.
\end{align}

Re-arranging the above inequality, we have 
\begin{align*}
  \frac{5}{8}\overline{\Delta}_{l+1}\leq \overline{\Delta}_1+\frac{1}{2}\functiongapboundconstant+1+4\log^2\frac{T}{\delta}+\frac{\sqrt{2C}}{\sqrt{L_0T}}+\frac{303L_0}{1792L_1^2}\leq \frac{5}{8}\functiongapboundconstant.
\end{align*}
The second inequality holds since 
$\functiongapboundconstant=\Gconstant$.

Therefore, $P_{l+1}\leq P_c$ also holds. 
So the induction is complete and we obtain the desired result. 
\end{proof}

\begin{proof}[Proof of Proposition \ref{proposition 1}]
  From \cite{ghadimi2016accelerated}, we have
  \begin{align*}
    \sumlimits{k=1}{t}\frac{\alpha_k}{\varGamma_k}=\frac{\alpha_1}{\varGamma_1}+\sumlimits{k=2}{t}\frac{\alpha_k}{\varGamma_k}=\frac{1}{\varGamma_1}+\sumlimits{k=2}{t}\frac{1}{\varGamma_k}\left(1-\frac{\varGamma_{k}}{\varGamma_{k-1}}\right)=\frac{1}{\varGamma_1}+\sumlimits{k=2}{t}\left(\frac{1}{\varGamma_k}-\frac{1}{\varGamma_{k-1}}\right)=\frac{1}{\varGamma_t}.
  \end{align*}
  Therefore, 
  \begin{align*}
    \varGamma_{t}\sumlimits{k=1}{t}\frac{\alpha_k}{\varGamma_k}=1.
  \end{align*}
  For any $t\geq 2$, we have
 \begin{align*}
  \varGamma_t=\left(1-\alpha_t\right)\varGamma_{t-1}=\frac{t-1}{t+1}\varGamma_{t-1}=\cdots=\frac{t-1}{t+1}\cdot\frac{t-2}{t}\cdots \frac{2-1}{2+1}=\frac{2}{t\left(t+1\right)}.
\end{align*}
Hence,
  \begin{align*}
    \left[\sumlimits{k=t}{T}\left(1-\alpha_k\right)\varGamma_k\right]\frac{\alpha_t}{\varGamma_t} & =\left[\sumlimits{k=t}{T}\frac{k-1}{k+1}\frac{2}{k\left(k+1\right)}\right]\cdot t\notag\\
    \leq & 2t \sumlimits{k=t}{T}\frac{1}{k\left(k+1\right)}\notag\\
    = & 2t\left(\frac{1}{t}-\frac{1}{T+1}\right) \leq 2.
  \end{align*}
\end{proof}

