\begin{proof}[Proof of Proposition \ref{proposition overline x_t - x_t}]
  Following from the iteration steps in Algorithm \ref{algorithm1} and referring to the proof in \cite{ghadimi2016accelerated}, we have 
  \begin{align*}
    \overline{x}_t-x_t = & \left(1-\alpha_t\right)[\tilde{x}_t-x_t]\notag\\
    = & \left(1-\alpha_t\right)[\overline{x}_{t-1}-x_{t-1}+\left(\theta_{t-1}-\gamma_{t-1}\right)g_{t-1}]\notag\\
    = & \left(1-\alpha_t\right)[\left(1-\alpha_{t-1}\right)\left(\tilde{x}_{t-1}-x_{t-1}\right)+\left(\theta_{t-1}-\gamma_{t-1}\right)g_{t-1}]\notag\\
    = & \left(1-\alpha_t\right)\sumlimits{k=1}{t-1}\left(\prod\limits_{j=k+1}^{t-1}\left(1-\alpha_j\right)\right)\left(\theta_k-\gamma_k\right)g_k\notag\\
    = & \left(1-\alpha_t\right)\sumlimits{k=1}{t-1}\frac{\varGamma_{t-1}}{\varGamma_{k}}\left(\theta_k-\gamma_k\right)g_k\notag\\
    = & \left(1-\alpha_t\right)\varGamma_{t-1}\sumlimits{k=1}{t-1}\frac{\alpha_k}{\varGamma_k}\frac{\left(\theta_k-\gamma_k\right)}{\alpha_k}g_k.
  \end{align*}
  By the convexity of square of the norm and \eqref{proposition 1.1}, we have 
  \begin{align}
    \label{overline x_t-x_t square norm}
    \|\overline{x}_t-x_t\|^2 = & \left\Vert\left(1-\alpha_t\right)\varGamma_{t-1}\sumlimits{k=1}{t-1}\frac{\alpha_k}{\varGamma_k} \frac{\left(\theta_k-\gamma_k\right)}{\alpha_k}  g_k\right\Vert^2\notag\\
    \leq & \left(1-\alpha_t\right)^2\varGamma_{t-1}\sumlimits{k=1}{t-1}\frac{\alpha_k}{\varGamma_k}\frac{\left(\theta_k-\gamma_k\right)^2}{\alpha_k^2}\|g_k\|^2\notag\\
    = & \left(1-\alpha_t\right)\varGamma_t\sumlimits{k=1}{t-1}\frac{\alpha_k}{\varGamma_k}\frac{\left(\theta_k-\gamma_k\right)^2}{\alpha_k^2}\|g_k\|^2.
  \end{align}
\end{proof}

  By the convexity of square of the norm and \eqref{proposition 1.1}, we have 
